/**
 * Pure data for the context-unselect tool, generated by the shared factory
 * in context-mark.ts (context-select and context-unselect differ only in
 * name and copy). This definition is also the ONLY tool given to the
 * context-autoselect subagent. No logic lives here — see
 * src/tools/context-mark.ts.
 */

import type { Static } from "typebox";

import { makeMarkToolDefinition } from "./context-mark.ts";

export const CONTEXT_UNSELECT_TOOL_DEFINITION = makeMarkToolDefinition("unselect");
export const CONTEXT_UNSELECT_PARAMETERS = CONTEXT_UNSELECT_TOOL_DEFINITION.parameters;

export type ContextUnselectParams = Static<typeof CONTEXT_UNSELECT_PARAMETERS>;
